        "body": "① 사업주는 고객 등 업무와 밀접한 관련이 있는 사람이 업무수행 과정에서 성적인 언동 등을 통하여 근로자에게 성적 굴욕감 또는 혐오감 등을 느끼게 하여 해당 근로자가 그로 인한 고충 해소를 요청할 경우 근무 장소 변경, 배치전환, 유급휴가의 명령 등 적절한 조치를 하여야 한다. <개정 2017. 11. 28., 2020. 5. 26.>\n② 사업주는 근로자가 제1항에 따른 피해를 주장하거나 고객 등으로부터의 성적 요구 등에 따르지 아니하였다는 것을 이유로 해고나 그 밖의 불이익한 조치를 하여서는 아니 된다. <개정 2020. 5. 26.>\n제3절 여성의 직업능력 개발 및 고용 촉진 <개정 2007.12.21>"
