        "body": "고용노동부장관은 법 제22조의5제2항에 따라 법 제21조 및 법 제21조의2에 따른 직장어린이집 설치ㆍ운영의 지원에 관한 업무와 법 제22조의5제1항에 따른 일ㆍ가정 양립 지원 기반 조성에 관한 업무를 다음 각 호의 어느 하나에 해당하는 기관 또는 법인에 위탁할 수 있다.\n1. 「공공기관의 운영에 관한 법률」 제5조제4항제2호에 따른 준정부기관\n2. 「정부출연연구기관 등의 설립ㆍ운영 및 육성에 관한 법률」 제8조에 따라 설립된 연구기관\n3. 「민법」 제32조에 따라 설립된 비영리법인으로서 일ㆍ가정 양립 지원 등의 사업 수행을 목적으로 설립된 법인\n제4장 분쟁의 예방과 해결"
