        "body": "① 고용노동부장관은 제14조(제15조의2제4항에 따라 준용되는 경우를 포함한다)에 따라 확정된 시정명령을 이행할 의무가 있는 사용자의 사업 또는 사업장에서 해당 시정명령의 효력이 미치는 근로자 이외의 기간제근로자 또는 단시간근로자에 대하여 차별적 처우가 있는지를 조사하여 차별적 처우가 있는 경우에는 그 시정을 요구할 수 있다.\n② 사용자가 제1항에 따른 시정요구에 따르지 아니하는 경우에는 제15조의2제2항부터 제5항까지의 규정을 준용한다. <개정 2020. 5. 26.>\n제5장 보칙"
