        "id": "labor-standards-decree-43조의2",
        "no": "제43조의2",
        "title": "임신기간 근로시간 단축의 신청",
        "body": "법 제74조제7항에 따라 근로시간 단축을 신청하려는 여성 근로자는 근로시간 단축 개시 예정일의 3일 전까지 임신기간, 근로시간 단축 개시 예정일 및 종료 예정일, 근무 개시 시각 및 종료 시각 등을 적은 문서(전자문서를 포함한다)에 의사의 진단서(같은 임신에 대하여 근로시간 단축을 다시 신청하는 경우는 제외한다)를 첨부하여 사용자에게 제출하여야 한다."
