        "id": "labor-standards-decree-43조의3",
        "no": "제43조의3",
        "title": "임신기간 업무의 시작 및 종료 시각의 변경",
        "body": "① 법 제74조제9항 본문에 따라 업무의 시작 및 종료 시각의 변경을 신청하려는 여성 근로자는 그 변경 예정일의 3일 전까지 임신기간, 업무의 시작 및 종료 시각의 변경 예정 기간, 업무의 시작 및 종료 시각 등을 적은 문서(전자문서를 포함한다)에 임신 사실을 증명하는 의사의 진단서(같은 임신에 대해 업무의 시작 및 종료 시각 변경을 다시 신청하는 경우는 제외한다)를 첨부하여 사용자에게 제출해야 한다.\n② 법 제74조제9항 단서에서 \"정상적인 사업 운영에 중대한 지장을 초래하는 경우 등 대통령령으로 정하는 경우\"란 다음 각 호의 어느 하나에 해당하는 경우를 말한다.\n1. 정상적인 사업 운영에 중대한 지장을 초래하는 경우\n2. 업무의 시작 및 종료 시각을 변경하게 되면 임신 중인 여성 근로자의 안전과 건강에 관한 관계 법령을 위반하게 되는 경우"
