        "title": "손해배상 청구의 신청",
        "body": "근로자는 「근로기준법」(이하 \"법\"이라 한다) 제19조제2항에 따라 사용자의 근로조건 위반을 이유로 손해배상을 청구하려면 별지 제1호서식의 근로조건 위반 손해배상 청구 신청서에 다음 각 호의 서류를 첨부하여 「노동위원회법」에 따른 지방노동위원회(이하 \"관할 지방노동위원회\"라 한다)에 제출하여야 한다.\n1. 근로계약서 사본\n2. 사용자가 근로조건을 위반하였다는 사실을 증명하는 자료"
